import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const jsonPath = new URL("../src/lib/data/i18n.json", import.meta.url);
const outPath = new URL("../src/lib/gui/i18n.keys.ts", import.meta.url);

const data = JSON.parse(readFileSync(jsonPath, "utf8"));
const keys = Object.keys(data.en).sort();

const body =
    "// * Generated by scripts/gen-i18n-keys.mjs — do not edit by hand.\n" +
    "export type I18nKey =\n" +
    keys.map((key) => "    | " + JSON.stringify(key)).join("\n") +
    ";\n";

writeFileSync(outPath, body, "utf8");
console.log(`wrote ${keys.length} keys to i18n.keys.ts`);
